import { Component, createMemo, createSignal, mergeProps, Show, untrack } from "solid-js";
import { JSX } from "solid-js/jsx-runtime";

import { ActiveDeviceTypeChangedEventName } from "#core/ui/input/input-events.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { HSlot, VSlot } from "#core/ui-next/components/slot.jsx";
import { TabContextProvider, useTabContext } from "#core/ui-next/components/tab.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useAspectRatio, useIsSmallScreen, useWindowSize } from "#core/ui-next/utilities/layout-utilities.js";

import { useAdvisorScreenContext } from "#base/ui-next/screens/advisor-council/advisor-screen-model.js";

import advisorStyles from "./advisor-screen.scss?url";

export interface AdvisorPortraitProps {
	title: string;
	type: AdvisorType;
	shrink?: boolean; //Shrink if below 1000p
}

const AdvisorPortraitComponent: Component<AdvisorPortraitProps> = (props) => {
	const mergedProps = mergeProps({ shrink: false }, props);
	const model = useAdvisorScreenContext();
	const isSmallScreen = useIsSmallScreen();
	return (
		<>
			{!isSmallScreen() || !mergedProps.shrink ? (
				<div class="relative flex self-center pb-2">
					<Icon
						class="council-advisor-bg bg-cover bg-no-repeat"
						name={`url("blp:adv_port_bk_highres")`}
					/>
					<div
						class="council-advisor-portrait absolute inset-0 bg-cover bg-no-repeat"
						style={{
							"background-image": `url(${model.advisorPortraitURL(mergedProps.type)})`,
						}}
					/>

					<Icon
						class="council-advisor-type-icon-bg absolute inset-0 bg-cover bg-no-repeat"
						name={`url("blp:adv_icon_bk_highres")`}
					/>
					<Icon
						class="council-advisor-type-icon absolute inset-0 bg-cover bg-no-repeat"
						name={`url("blp:adv_badge_${mergedProps.title.toLowerCase()}_highres")`}
					/>
				</div>
			) : (
				<div class="w-full h-13">
					<div class="relative w-13 h-13 self-center -top-2">
						<Icon
							class="council-advisor-type-icon-bg-compact absolute inset-0 bg-cover bg-no-repeat w-21 h-21"
							name={`url("blp:adv_icon_bk_highres")`}
						/>
						<Icon
							class="absolute bg-cover bg-no-repeat w-13 h-13"
							name={`url("blp:adv_badge_${mergedProps.title.toLowerCase()}")`}
						/>
						<div
							class="absolute flex flex-col items-center justify-center self-center -bottom-3 -right-8"
							style={{ "border-radius": "50%" }}
						>
							<Icon
								class="bg-no-repeat bg-contain bg-center w-11 h-11"
								name={`url(${model.isFollowing(mergedProps.type) ? "blp:advScreen_icon_following_720" : "blp:advScreen_icon_notFollowing_720"})`}
							/>
						</div>
					</div>
				</div>
			)}
		</>
	);
};

export interface AdvisorQuoteContainerProps extends JSX.HTMLAttributes<HTMLElement> {
	iconSrc?: string;
	iconElement?: JSX.Element;
	isFollowed: boolean;
	useScrollProxy?: boolean;
}

export const AdvisorQuoteContainer: Component<AdvisorQuoteContainerProps> = (props) => {
	const mergedProps = mergeProps({ useScrollProxy: false }, props);
	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	return (
		<div
			class={`advisor-quote-container relative`}
			data-name="Ornate-Card"
		>
			<Show
				when={!isSmallScreen()}
				fallback={<div class="advisor-quote-frame-top-compact absolute -left-0 bg-center w-full h-4" />}
			>
				<div
					class="advisor-quote-frame-top absolute -top-4 -left-0 bg-center"
					style={{
						"background-image": `url(blp:adv_decorleft_${mergedProps.isFollowed ? "following" : "notfollowing"})`,
					}}
				/>
				<div
					class="advisor-quote-frame-top absolute  -top-4 -right-0 -scale-x-100 h-7 bg-center"
					style={{
						"background-image": `url(blp:adv_decorleft_${mergedProps.isFollowed ? "following" : "notfollowing"})`,
					}}
				/>
				<div
					class="-top-13 absolute flex flex-col items-center justify-center self-center"
					style={{ "border-radius": "50%" }}
				>
					<Icon
						class="advisor-quote-follow-icon bg-no-repeat bg-contain bg-center"
						name={
							mergedProps.isFollowed
								? "url(blp:advScreen_icon_notFollowing_highres)"
								: "url(blp:advScreen_icon_following_highres)"
						}
					/>
				</div>
			</Show>

			<ScrollArea
				class={`flex justify-center text-2xl flex-auto overflow-hidden ${isMobile ? "my-3" : "my-2"}`}
				role="textbox"
				useProxy={mergedProps.useScrollProxy}
				allowGamepadPan={mergedProps.useScrollProxy}
				reserveSpace={IsControllerActive()}
			>
				{props.children}
			</ScrollArea>
		</div>
	);
};

export interface AdvisorCardProps {
	type: AdvisorType;
	title: string;
	isInitialPopup: boolean;
	activatable?: boolean;
}

const AdvisorCardComponent: Component<AdvisorCardProps> = (props) => {
	const mergedProps = mergeProps({ activatable: false }, props);

	const model = useAdvisorScreenContext();

	const isFollowing = () => model.isFollowing(mergedProps.type);

	// Show latest quote if in council room or the introductory one if in pop-up
	const advisorQuote = createMemo(() =>
		mergedProps.isInitialPopup ? model.advisorInitialQuote(props.title) : model.advisorsLastQuote(mergedProps.type),
	);

	const isSelected = createMemo(() => model.getSelectedAdvisorCard() === mergedProps.type);
	const [isHovered, setIsHovered] = createSignal<boolean>(false);

	const windowHeight = useWindowSize();
	const isSmallScreen = useIsSmallScreen();
	const aspectRatio = useAspectRatio();

	const isMobile = ViewExperience() == UIViewExperience.Mobile;

	let tabContext: TabContextProvider | undefined = undefined;

	const isInitialPopup = untrack(() => props.isInitialPopup);

	if (!isInitialPopup) {
		tabContext = useTabContext();
	}

	window.addEventListener(ActiveDeviceTypeChangedEventName, () => {
		setIsHovered(false);
	});

	return (
		<div
			class={`advisor-card flex flex-col justify-end relative flex-1 ${isSmallScreen() || aspectRatio() <= 1.335 ? "mx-1" : "mx-4"}`}
		>
			<AudioContextProvider
				vars={{
					advisorType: mergedProps.title.toLowerCase(),
					following: (!isFollowing()).toString(),
				}}
			>
				<Activatable
					class={`w-full h-full absolute`}
					onFocusIn={() => {
						setIsHovered(true);
						model.setSelectedAdvisorCard(mergedProps.type);
					}}
					onFocusOut={() => {
						setIsHovered(false);
					}}
					onMouseEnter={() => {
						setIsHovered(true);
					}}
					onMouseLeave={() => {
						setIsHovered(false);
					}}
					onActivate={() => {
						if (props.isInitialPopup) {
							if (IsControllerActive()) {
								model.clickClosePopup();
							} else {
								model.playFollowAudio(mergedProps.type);
								if (!isFollowing()) {
									model.follow(mergedProps.type);
								} else {
									model.unfollow(mergedProps.type);
								}
							}
						} else if (tabContext) {
							// Navigate to a given advisors screen
							tabContext.activate(mergedProps.title);
							useAudio("AdvisorScreen")("navigate-tab");
						}
					}}
					tabIndex={-1}
				>
					<div class="quest-advisor-card-filigree absolute w-full h-20 -top-10" />
					<Show when={mergedProps.activatable}>
						<div
							class={`advisor-card-focusable absolute`}
							classList={{
								"advisor-card-opaque": isHovered(),
							}}
						>
							<div class="w-full h-full">{`LOC_ADVISOR_${mergedProps.title}_NAME`}</div>
						</div>
					</Show>
					<div
						class="w-full items-center justify-center self-center"
						classList={{ "-mt-21": !isSmallScreen() }}
					>
						<HSlot class="justify-center">
							<Show
								when={!props.isInitialPopup || IsControllerActive()}
								fallback={
									<div
										class={`${isSmallScreen() ? "-mt-4" : aspectRatio() <= 1.25 ? "mt-10" : "-mt-6"}`}
									>
										<AdvisorPortrait
											title={mergedProps.title}
											type={mergedProps.type}
											shrink
										/>
									</div>
								}
							>
								<div class={`${isSmallScreen() ? "-mt-4" : aspectRatio() <= 1.25 ? "mt-10" : "-mt-6"}`}>
									<AdvisorPortrait
										title={mergedProps.title}
										type={mergedProps.type}
										shrink
									/>
								</div>
							</Show>
						</HSlot>
						<HSlot class="justify-center w-full">
							<div
								class={`advisor-card-title font-title font-black tracking-100 uppercase w-full ${isSmallScreen() || (aspectRatio() <= 1.335 && windowHeight() < 1080) ? "text-sm" : "base"}`}
								role="menuitem"
							>
								<L10n.Stylize
									class={`${isSmallScreen() ? (isMobile ? "mt-4" : "mt-6") : "mt-5 mb-3"} self-center text-center font-fit-shrink`}
									style={{ width: "95%" }}
									text={`LOC_ADVISOR_${mergedProps.title}_NAME`}
								/>
							</div>
						</HSlot>
					</div>
					<div
						class={`${isMobile && isSmallScreen() ? "pt-1" : "pt-10"} pb-3 flex-1 ${isSmallScreen() ? "px-2" : "px-7"}`}
					>
						<AdvisorQuoteContainer
							isFollowed={!isFollowing()}
							useScrollProxy={isSelected()}
						>
							<L10n.Stylize
								class={`${isMobile && isSmallScreen() ? "my-1 mx-4" : "mt-6 mx-5"} text-accent-3 self-center ${isSmallScreen() ? "text-sm" : "text-base"}`}
								text={advisorQuote()}
							/>
						</AdvisorQuoteContainer>
					</div>
					<Show when={!IsControllerActive()}>
						<VSlot
							class={`flow-row justify-center align-botto  pb-6 ${isSmallScreen() ? "px-3 pt-2\\.5" : "px-8 pt-1"}`}
						>
							<Button
								size={isSmallScreen() ? "small" : "standard"}
								onActivate={() => {
									if (!isFollowing()) model.follow(mergedProps.type);
									else model.unfollow(mergedProps.type);
								}}
								class={"w-full h-10 text-xs align-bottom"}
								disableFocus
							>
								<div
									class={`w-full flex items-center justify-center pointer-events-none`}
									style={{ width: "88%" }}
								>
									<Icon
										class="size-8 bg-no-repeat bg-contain bg-center mx-1 pointer-events-none"
										name={
											isFollowing()
												? "url(blp:advScreen_button_following_highres)"
												: "url(blp:advScreen_button_notFollowing_highres)"
										}
									/>
									<Show
										when={isFollowing()}
										fallback={
											<L10n.Stylize
												text={"LOC_ADVISOR_COUNCIL_FOLLOW"}
												class={`font-fit-shrink pointer-events-none ${isSmallScreen() ? "text-2xs" : "text-base"}`}
											/>
										}
									>
										<L10n.Stylize
											text={"LOC_ADVISOR_COUNCIL_UNFOLLOW"}
											class={`font-fit-shrink pointer-events-none ${isSmallScreen() ? "text-2xs" : "text-base"}`}
										/>
									</Show>
								</div>
							</Button>
						</VSlot>
					</Show>
				</Activatable>
			</AudioContextProvider>
		</div>
	);
};

export const AdvisorPortrait = ComponentRegistry.register({
	name: "AdvisorPortrait",
	createInstance: AdvisorPortraitComponent,
	styles: [advisorStyles],
});

export const AdvisorCard = ComponentRegistry.register({
	name: "AdvisorCard",
	createInstance: AdvisorCardComponent,
	styles: [advisorStyles],
});
